  "verdict": "request_changes",
  "summary": "Candidate implementation of active() incorrectly treats the expiration timestamp as active, violating the strict-before specification.",
  "findings": [
    {
      "finding_id": "F1",
      "file": "candidate.py",
      "line_start": 2,
